  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return api.state.new_record == null || api.state.new_record == "";
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {

  var empty = !(api.state.Atleast_one_flow_selected);

  if (empty == true){
    return "All mandatory fields must be filled to save record";
  }
  return ' Your settings for Sensitive data detection are successfully modified';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.Atleast_one_flow_selected;
}

/**
  * @param {params} params
